import json
import os
import io
import collections
import datetime
import boxsdk

# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------
COUNTY_FIELD = os.environ.get("COUNTY_FIELD", "county")
STATE_FIELD  = os.environ.get("STATE_FIELD",  "state")
BOX_FOLDER_ID   = os.environ.get("BOX_ROOT_FOLDER_ID", "334546874262")
BOX_CONFIG_PATH = os.environ.get("BOX_CONFIG_PATH", "/run/secrets/box_config.json")
MAP_TITLE    = os.environ.get("MAP_TITLE", "Survey Responses by County")


def run(inputs):
    records = inputs.get("records", [])

    # ------------------------------------------------------------------
    # 1. Aggregate counts keyed by "State|County" (case-normalised)
    # ------------------------------------------------------------------
    counts = collections.Counter()
    for rec in records:
        county = str(rec.get(COUNTY_FIELD, "")).strip().title()
        state  = str(rec.get(STATE_FIELD,  "")).strip().upper()
        if county and state:
            counts[f"{state}|{county}"] += 1

    counts_list = [
        {"key": k, "state": k.split("|")[0], "county": k.split("|")[1], "value": v}
        for k, v in counts.items()
    ]

    # ------------------------------------------------------------------
    # 2. Build self-contained D3 v7 choropleth HTML
    # ------------------------------------------------------------------
    counts_json = json.dumps(counts_list)
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<title>{MAP_TITLE}</title>
<style>
  body {{ margin:0; font-family: sans-serif; background:#f4f4f4; }}
  h1   {{ text-align:center; padding:16px 0 4px; font-size:1.3rem; color:#333; }}
  #map {{ display:block; margin:0 auto; }}
  .tooltip {{
    position:absolute; pointer-events:none;
    background:rgba(0,0,0,.75); color:#fff;
    padding:6px 10px; border-radius:4px; font-size:.85rem;
    opacity:0; transition:opacity .15s;
  }}
  .legend-label {{ font-size:.75rem; fill:#555; }}
</style>
</head>
<body>
<h1>{MAP_TITLE}</h1>
<div class="tooltip" id="tip"></div>
<svg id="map" width="960" height="600"></svg>

<script src="https://cdn.jsdelivr.net/npm/d3@7/dist/d3.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/topojson-client@3/dist/topojson-client.min.js"></script>
<script>
(async () => {{
  const counts = {counts_json};
  const lookup = {{}};
  counts.forEach(d => {{ lookup[d.key] = d.value; }});

  // Fetch US Atlas counties topology (CDN)
  const us = await d3.json(
    "https://cdn.jsdelivr.net/npm/us-atlas@3/counties-albers-10m.json"
  );

  // FIPS -> name mapping from topology
  const countyNames = {{}};
  topojson.feature(us, us.objects.counties).features.forEach(f => {{
    countyNames[f.id] = f.properties.name;
  }});
  const stateNames = {{}};
  topojson.feature(us, us.objects.states).features.forEach(f => {{
    stateNames[f.id] = f.properties.name;
  }});

  // Build FIPS lookup from state+county name
  const fipsLookup = {{}};
  topojson.feature(us, us.objects.counties).features.forEach(f => {{
    const stFips = f.id.slice(0,2);
    const stAbbr = stateNames[stFips] ? stateNames[stFips].toUpperCase().slice(0,2) : "";
    const key = stAbbr + "|" + f.properties.name;
    fipsLookup[key] = f.id;
  }});

  const getValue = (feature) => {{
    const stFips = feature.id.slice(0,2);
    const stName = (stateNames[stFips] || "").toUpperCase().slice(0,2);
    const key = stName + "|" + feature.properties.name;
    return lookup[key] || 0;
  }};

  const maxVal = d3.max(counts, d => d.value) || 1;
  const color  = d3.scaleSequential(d3.interpolateBlues).domain([0, maxVal]);

  const svg  = d3.select("#map");
  const path = d3.geoPath();
  const tip  = d3.select("#tip");

  // Counties
  svg.append("g")
    .selectAll("path")
    .data(topojson.feature(us, us.objects.counties).features)
    .join("path")
      .attr("fill", d => {{ const v = getValue(d); return v ? color(v) : "#e8e8e8"; }})
      .attr("d", path)
      .on("mousemove", (event, d) => {{
        const v = getValue(d);
        const stFips = d.id.slice(0,2);
        tip.style("opacity",1)
           .style("left", (event.pageX+12)+"px")
           .style("top",  (event.pageY-28)+"px")
           .html(`<b>${{d.properties.name}}, ${{stateNames[stFips]||""}}</b><br/>Responses: ${{v}}`);
      }})
      .on("mouseleave", () => tip.style("opacity",0));

  // State borders
  svg.append("path")
    .datum(topojson.mesh(us, us.objects.states, (a,b) => a !== b))
    .attr("fill","none").attr("stroke","#fff").attr("stroke-width",1)
    .attr("d", path);

  // Legend
  const lw=200, lh=12, lx=700, ly=550;
  const defs = svg.append("defs");
  const grad = defs.append("linearGradient").attr("id","leg-grad");
  grad.selectAll("stop")
    .data(d3.ticks(0,1,10))
    .join("stop")
      .attr("offset", d => d)
      .attr("stop-color", d => color(d*maxVal));

  svg.append("rect")
    .attr("x",lx).attr("y",ly).attr("width",lw).attr("height",lh)
    .attr("fill","url(#leg-grad)");
  svg.append("text").attr("class","legend-label")
    .attr("x",lx).attr("y",ly+lh+12).text("0");
  svg.append("text").attr("class","legend-label")
    .attr("x",lx+lw).attr("y",ly+lh+12).attr("text-anchor","end").text(maxVal);
  svg.append("text").attr("class","legend-label")
    .attr("x",lx+lw/2).attr("y",ly-4).attr("text-anchor","middle").text("Response count");
}})();
</script>
</body>
</html>"""

    # ------------------------------------------------------------------
    # 3. Upload to Box
    # ------------------------------------------------------------------
    timestamp = datetime.datetime.utcnow().strftime("%Y%m%d_%H%M%S")
    filename  = f"county_map_{timestamp}.html"

    with open(BOX_CONFIG_PATH) as f:
        box_cfg = boxsdk.JWTAuth.from_settings_dictionary(json.load(f))
    client  = boxsdk.Client(box_cfg)
    folder  = client.folder(BOX_FOLDER_ID)
    stream  = io.BytesIO(html.encode("utf-8"))
    uploaded = folder.upload_stream(stream, filename)

    box_path = f"box://{BOX_FOLDER_ID}/{uploaded.id}/{filename}"

    return {
        "records":  records,
        "map_path": box_path,
    }
